import{_ as o,o as d,c,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/GET.md","filePath":"manual-zh/GET.md","lastUpdated":1785684581000}'),E={name:"manual-zh/GET.md"};function t(n,e,p,r,_,P){return d(),c("div",null,[...e[0]||(e[0]=[a(`<h3 id="_9-3-get" tabindex="-1">9.3 GET <a class="header-anchor" href="#_9-3-get" aria-label="Permalink to &quot;9.3 GET&quot;">​</a></h3><pre><code>GET
        /FILE={’file_name’,file_handle}
        /DROP=var_list
        /KEEP=var_list
        /RENAME=(src_names=target_names)…
        /ENCODING=’encoding’
</code></pre><p><code>GET</code> 清空当前字典和活动数据集，并用指定文件中的字典和数据替换它们。</p><p><code>FILE</code> 子命令是唯一必需的子命令。将要读取的 SPSS 系统文件、SPSS/PC+ 系统文件或 SPSS 便携文件指定为字符串文件名或文件句柄（见 <a href="./File-Handles">文件句柄</a>）。</p><p>默认情况下，将读取文件中的所有变量。<code>DROP</code> 子命令可用于指定不读取的变量列表。相反，<code>KEEP</code> 子命令可用于指定要读取的变量，所有其他变量不读取。</p><p>通常，文件中的变量保留其保存时的名称。使用 <code>RENAME</code> 子命令更改这些名称。在括号内指定变量名列表，后跟等号（‘=’）以及它们应重命名为的名称。单个 <code>RENAME</code> 子命令可以包含多个带括号的变量名组。可以使用形如 <code>/RENAME=(A B=B A)</code> 的 <code>RENAME</code> 子命令交换变量的名称。</p><p><code>RENAME</code> 子命令的替代语法允许省略括号。这样做时，一次只能重命名一个变量。例如 <code>/RENAME=A=B</code>。此替代语法已弃用。</p><p><code>DROP</code>、<code>KEEP</code> 和 <code>RENAME</code> 按从左到右的顺序执行。每个可以出现任意次数。<code>GET</code> 从不修改磁盘上的文件。只有从文件读取的活动数据集受这些子命令影响。</p><p>PSPP 在可能的情况下会自动检测文件中字符串数据的编码。旧 SPSS 系统文件的字符编码并非总能正确猜测，而 SPSS/PC+ 系统文件不包含任何编码指示。使用 <code>ENCODING</code> 子命令并将 IANA 字符集名称作为其字符串参数以覆盖默认值。使用 <code>SYSFILE INFO</code> 分析系统文件可能有效的编码。<code>ENCODING</code> 子命令是 PSPP 的扩展。</p><p><code>GET</code> 不会导致数据被读取，只会读取字典。数据在稍后执行过程时读取。</p><p>使用 <code>GET</code> 读取便携文件是 PSPP 的扩展。</p>`,11)])])}const l=o(E,[["render",t]]);export{S as __pageData,l as default};
